{
  "schema_id": "code.facts",
  "schema_version": 1,
  "workspace_files": [
    "README-task.md",
    "ingest/__init__.py",
    "ingest/parser.py",
    "ingest/pipeline.py",
    "ingest/store.py",
    "tests/test_public_pipeline.py"
  ],
  "stated_goal": "让 ingest 流水线端到端跑通，坏行要留痕不要丢。",
  "public_contract": {
    "source": "README-task.md",
    "entry": "ingest.pipeline.run(lines, store, quarantine)",
    "exit_code": {
      "all_stored": 0,
      "any_quarantined": "non-zero"
    },
    "quarantine": {
      "type": "list mutated by append",
      "item_fields": {
        "line_no": "1-based line number",
        "raw": "original line text without trailing newline",
        "reason": "string"
      }
    },
    "coverage_rule": "every input line must land in store or quarantine; never neither"
  },
  "modules": {
    "ingest/__init__.py": {
      "content": "empty"
    },
    "ingest/parser.py": {
      "exports": ["SUPPORTED_CURRENCIES", "BadRow", "parse_line"],
      "SUPPORTED_CURRENCIES": ["USD", "EUR"],
      "parse_line": {
        "input": "one line string",
        "success_return": {
          "type": "dict",
          "keys": ["id", "amount_cents", "currency"]
        },
        "failure": "raises BadRow (ValueError subclass)",
        "steps": [
          "rstrip only '\\n', then split on ','",
          "require exactly 3 fields",
          "strip whitespace on each field",
          "reject empty identifier",
          "amount: int(round(float(amount) * 100)); ValueError -> BadRow",
          "currency must be in SUPPORTED_CURRENCIES after .upper(); stored uppercased"
        ],
        "reject_reasons_observed_in_tests": [
          "wrong field count",
          "missing id",
          "non-numeric amount",
          "unsupported currency (e.g. JPY)"
        ]
      }
    },
    "ingest/store.py": {
      "Record": {
        "kind": "frozen dataclass",
        "fields": ["id: str", "amount_cents: int", "currency: str"]
      },
      "Store": {
        "semantics": "one record per id; re-add replaces",
        "add": "indexes by record.id attribute (not dict key)",
        "get": "returns Record or KeyError if missing",
        "count": "len of internal dict",
        "ids": "sorted list of ids"
      }
    },
    "ingest/pipeline.py": {
      "run": {
        "signature": "run(lines, store, quarantine)",
        "current_body": [
          "for line in lines: record = parse_line(line); store.add(record)",
          "always return 0"
        ],
        "does_not": [
          "catch BadRow",
          "append to quarantine",
          "assign 1-based line_no",
          "strip trailing newline for quarantine raw",
          "convert parse_line dict into store.Record",
          "return non-zero when any line is bad"
        ]
      }
    }
  },
  "type_mismatch": {
    "description": "parse_line returns a dict; Store.add uses record.id. Passing the dict would raise AttributeError. Visible tests never call pipeline.run or Store.add with a dict.",
    "implication": "even all-good rows cannot currently complete store.add unless callers wrap the dict as Record first"
  },
  "visible_tests": {
    "path": "tests/test_public_pipeline.py",
    "count": 6,
    "scope": "parser and store in isolation; no pipeline.run coverage",
    "cases": [
      "test_parse_line_reads_a_good_row: 'INV-1,10.50,usd\\n' -> id INV-1, amount_cents 1050, currency USD",
      "test_parse_line_rejects_a_bad_row parametrize: 'INV-1,10.50'; ',10.50,USD'; 'INV-2,ten,USD'; 'INV-3,1.00,JPY'",
      "test_store_keeps_one_record_per_id: replace on same id, count 2, last amount_cents 1"
    ],
    "last_run": {
      "command": "pytest tests/test_public_pipeline.py",
      "result": "6 passed"
    }
  },
  "gaps_vs_contract": [
    "pipeline.run does not quarantine BadRow; exception escapes",
    "pipeline.run never mutates quarantine",
    "pipeline.run always returns 0",
    "no line numbering",
    "dict vs Record: store.add expects attribute access",
    "no visible test for end-to-end run, exit codes, or quarantine shape",
    "blank/emp
